USER_SCRIPT = r'''using System;
using System.Collections.Generic;
using Script.Methods;

// Generated by VT STUDIO. Change product logic only inside USER CODE regions.
public partial class UserScript : ScriptMethods, IProcessMethods
{
    private const int AiLabelCapacity = 4096;
    private const bool UseAi = __USE_AI__;

    public void Init() { }

    public bool Process()
    {
        string[] types = (NGtype ?? "").Split('-');
        for (int i = 0; i < types.Length; i++) types[i] = types[i].Trim();
        bool aiNG = UseAi && aiResult == 0;
        string[] labels = new string[0];
        bool labelsReadOK = !aiNG || TryReadAiLabels(out labels);
        bool configError = false;
        string ngName = "OK";
        bool hasFirstNG = false;
        string[] bits = new string[types.Length];

        for (int i = 0; i < types.Length; i++)
        {
            string type = types[i];
            bool isNG = aiNG && Array.IndexOf(labels, type) >= 0;
            // USER CODE BEGIN IndependentJudge
__INDEPENDENT__
            // USER CODE END IndependentJudge
            if (type == "") { isNG = true; configError = true; }
            bits[i] = isNG ? "0" : "1";
            if (isNG && !hasFirstNG) { ngName = type; hasFirstNG = true; }
        }
        if (aiNG)
        {
            string reason = null;
            if (!labelsReadOK) reason = "AI异常，标签数组读取失败或数量无效";
            else if (labels.Length == 0) reason = "AI异常，标签为空";
            else
            {
                List<string> unmatched = new List<string>();
                foreach (string label in labels)
                    if (Array.IndexOf(types, label) < 0) unmatched.Add(label);
                if (unmatched.Count > 0)
                    reason = "AI异常，标签未匹配NGtype：" + string.Join("、", unmatched.ToArray());
            }
            if (reason != null)
            {
                configError = true;
                ngName = hasFirstNG ? ngName + "；" + reason : reason;
            }
        }
        string finalName = configError ? "分类或配置异常；" + ngName : ngName;
        outResult_index = string.Join("|", bits);
        NG_name = finalName;
        NG_saveImg = speed >= 起始存图速度 ? 1 : 0;
        NG_imgName = "(" + speed + ")" + finalName + "_" + DateTime.Now.ToString("yyyyMMddHHmmss_fff");
        return !configError;
    }

    private bool TryReadAiLabels(out string[] labels)
    {
        labels = new string[0];
        string[] raw = new string[AiLabelCapacity];
        int count;
        int result = GetStringArrayValue("Label_name", ref raw, out count);
        if (result != 0 || raw == null || count < 0 || count > raw.Length) return false;
        List<string> normalized = new List<string>();
        for (int i = 0; i < count; i++)
        {
            string label = (raw[i] ?? "").Trim();
            // USER CODE BEGIN LabelNormalize
__NORMALIZE__
            // USER CODE END LabelNormalize
            if (label != "" && !normalized.Contains(label)) normalized.Add(label);
        }
        labels = normalized.ToArray();
        return true;
    }
}
'''

HARNESS = r'''using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using System.Text;
using System.Web.Script.Serialization;

// Offline API double only. Do NOT copy this file into VisionMaster.
namespace Script.Methods
{
    public interface IProcessMethods { void Init(); bool Process(); }
    public class ScriptMethods
    {
        protected int nErrorCode;
        public Dictionary<string, object> Inputs = new Dictionary<string, object>();
        public Dictionary<string, object> Outputs = new Dictionary<string, object>();
        public Dictionary<string, object> Case;
        public int LabelReadCalls;
        public int GetIntValue(string name, ref int value)
        {
            object raw;
            if (!Inputs.TryGetValue(name, out raw)) return 1;
            value = Convert.ToInt32(raw); return 0;
        }
        public int GetStringValue(string name, ref string value)
        {
            object raw;
            if (!Inputs.TryGetValue(name, out raw)) return 1;
            value = raw == null ? null : Convert.ToString(raw); return 0;
        }
        public int GetStringArrayValue(string name, ref string[] raw, out int count)
        {
            LabelReadCalls++;
            object source;
            Inputs.TryGetValue(name, out source);
            IList list = source as IList;
            count = list == null ? 0 : list.Count;
            if (Case.ContainsKey("label_count")) count = Convert.ToInt32(Case["label_count"]);
            if (source == null || (Case.ContainsKey("label_null") && Convert.ToBoolean(Case["label_null"]))) raw = null;
            else if (list != null)
                for (int i = 0; i < Math.Min(raw.Length, list.Count); i++) raw[i] = list[i] == null ? null : Convert.ToString(list[i]);
            return Case.ContainsKey("label_read_status") ? Convert.ToInt32(Case["label_read_status"]) : 0;
        }
        public int SetIntValue(string name, int value) { Outputs[name] = value; return 0; }
        public int SetStringValue(string name, string value) { Outputs[name] = value; return 0; }
    }
}

public static class ScriptHarness
{
    public static int Main(string[] args)
    {
        Console.OutputEncoding = new UTF8Encoding(false);
        var json = new JavaScriptSerializer { MaxJsonLength = 16000000 };
        try
        {
            var cases = (object[])json.DeserializeObject(File.ReadAllText(args[0], Encoding.UTF8));
            var rows = new List<object>();
            foreach (object item in cases)
            {
                var data = (Dictionary<string, object>)item;
                var script = new UserScript();
                script.Case = data;
                foreach (var kv in data) script.Inputs[kv.Key] = kv.Value;
                script.Init();
                bool result = script.Process();
                var row = new Dictionary<string, object> {
                    {"process_return", result}, {"outputs", script.Outputs},
                    {"label_read_calls", script.LabelReadCalls}
                };
                rows.Add(row);
            }
            Console.Write(json.Serialize(rows)); return 0;
        }
        catch (Exception e) { Console.Error.WriteLine(e.ToString()); return 1; }
    }
}
'''
